import { randomUUID } from "node:crypto";
import type { WorkerOwnership } from "../infra/workerOwnership";
import type { InternalRunRow } from "./store";
import { readEnvelope, captureCuts } from "./envelope";
import { capture, instantiate } from "./capture";
import type { StoredCapture, CaptureCheckpoint } from "./capture";
export async function retireInternalRuns(ownership: WorkerOwnership) {
  await ownership.transaction(async (db) => {
    await db.query(`UPDATE "InternalModel2Run" SET status='interrupted',reason='Worker restarted; last durable prefix retained. Exact continuation is unsupported.',"updatedAt"=now() WHERE status='running'`);
    await db.query(`UPDATE "InternalModel2Run" r SET status='failed',reason='Durable queue delivery exhausted before execution',"updatedAt"=now()
      WHERE status='queued' AND EXISTS (SELECT 1 FROM "Outbox" o WHERE o."eventType"='model2-internal-created' AND o.status='failed' AND o.payload->>'internalModel2RunId'=r.id)`);
  });
}
export async function failInternalDelivery(ownership: WorkerOwnership, id: string) {
  await ownership.transaction(async (db) => { await db.query(`UPDATE "InternalModel2Run" SET status='failed',reason='Durable queue delivery exhausted before execution',"updatedAt"=now() WHERE id=$1 AND status='queued'`, [id]); });
}
export async function executeInternalRun(id: string, ownership: WorkerOwnership) {
  const claimed = await ownership.transaction(async (db) => {
    const row = (await db.query<InternalRunRow>('SELECT * FROM "InternalModel2Run" WHERE id=$1 FOR UPDATE', [id])).rows[0];
    if (!row || !["queued", "running"].includes(row.status)) return null;
    if (row.status === "running") { await db.query(`UPDATE "InternalModel2Run" SET status='interrupted',reason='Prior delivery stopped without a terminal commit; no resume',"updatedAt"=now() WHERE id=$1`, [id]); return null; }
    try {
      if (!(await db.query('SELECT 1 FROM "InternalModel2Grant" WHERE "userId"=$1', [row.ownerId])).rowCount) throw Error("Internal authorization revoked before execution");
      const input = readEnvelope(row.input, row.inputHash);
      if (input.runId !== row.id || input.ownerId !== row.ownerId) throw Error("Recorded execution owner/identity mismatch");
      const token = randomUUID();
      await db.query('UPDATE "InternalModel2Run" SET status=\'running\',token=$2,"updatedAt"=now() WHERE id=$1', [id, token]);
      return { input, token };
    } catch (error) {
      await db.query('UPDATE "InternalModel2Run" SET status=\'failed\',reason=$2,"updatedAt"=now() WHERE id=$1', [id, message(error)]); return null;
    }
  });
  if (!claimed) return;
  let sequence = 0;
  let history: CaptureCheckpoint[] = [];
  const stop = async (reason: string) => ownership.transaction(async (db) => {
    await db.query('UPDATE "InternalModel2Run" SET status=\'interrupted\',reason=$3,"updatedAt"=now() WHERE id=$1 AND token=$2 AND status=\'running\'', [id, claimed.token, reason.slice(0, 500)]);
  });
  async function persist(value: StoredCapture, final: boolean, failure: string | null) {
    return ownership.transaction(async (db) => {
      const row = (await db.query<InternalRunRow>('SELECT * FROM "InternalModel2Run" WHERE id=$1 AND token=$2 AND status=\'running\' FOR UPDATE', [id, claimed!.token])).rows[0];
      if (!row) return false;
      if (row.sequence !== sequence) throw Error("Durable capture sequence changed");
      const granted = (await db.query('SELECT 1 FROM "InternalModel2Grant" WHERE "userId"=$1', [row.ownerId])).rowCount;
      const cancelled = row.cancelRequested || !granted, status = cancelled ? "cancelled" : failure ? "failed" : final ? "completed" : "running";
      const reason = !granted ? "Internal authorization revoked; stopped at the next capture boundary" : row.cancelRequested ? "Cancellation requested; stopped at the next capture boundary" : failure;
      await db.query('UPDATE "InternalModel2Run" SET status=$3,evidence=$4,sequence=$5,"throughUs"=$6,reason=$7,"updatedAt"=now() WHERE id=$1 AND token=$2 AND status=\'running\'', [id, claimed!.token, status, value, value.sequence, value.throughUs, reason]);
      sequence = value.sequence; return status === "running";
    });
  }
  try {
    const runtime = instantiate(claimed.input), cuts = captureCuts(claimed.input);
    for (const at of cuts) {
      await ownership.assertHeld();
      let failure: string | null = null;
      try { runtime.advanceTo(at); } catch (error) { failure = message(error); }
      const value = capture(runtime, claimed.input, sequence + 1, history);
      if (!await persist(value, at === runtime.horizon, failure)) return;
      history = value.checkpoints;
    }
  } catch (error) {
    // Advanced work whose capture did not commit is never replayed as continuation.
    // If this write also fails, startup/re-delivery will retire the running row.
    await stop(`Execution/persistence interrupted: ${message(error)}; last durable prefix retained`);
  }
}
const message = (error: unknown) => (error instanceof Error ? error.message : "Internal execution failed").slice(0, 400);

import { Router, json } from "express";
import { z } from "zod";
import { NotFoundError, ValidationError } from "../utils/errors";
import { admissionSchema, CompilationRefusal } from "./envelope";
import { admit, hasInternalGrant, ownedRun, requestCancellation, internalDatabase } from "./store";
import { internalReport, reportHtml, replayStored } from "./report";
import { workspaceRouter } from "./workspace";
export const internalModel2Router = Router();
internalModel2Router.use(async (_req, res, next) => {
  if (!await hasInternalGrant(res.locals.userId)) throw new NotFoundError();
  res.set("Cache-Control", "no-store"); res.set("X-Content-Type-Options", "nosniff"); next();
});
internalModel2Router.use(json({ limit: "256kb" }));
internalModel2Router.use(workspaceRouter);
internalModel2Router.post("/runs", async (req, res) => {
  const parsed = admissionSchema.safeParse(req.body);
  if (!parsed.success) throw new ValidationError(parsed.error.issues.map((e) => `${e.path.join(".")}: ${e.message}`).join("; "));
  try {
    const result = await admit(res.locals.userId, parsed.data);
    res.status(result.created ? 202 : 200).json({ success: true, id: result.run.id, status: result.run.status, inputHash: result.run.inputHash, created: result.created });
  } catch (error) {
    if (error instanceof CompilationRefusal) { res.status(422).json({ success: false, message: error.message, diagnostics: error.diagnostics }); return; }
    throw error;
  }
});
internalModel2Router.get("/runs", async (_req, res) => {
  const rows = await internalDatabase.query('SELECT id,status,"inputHash",sequence,"throughUs",reason,"createdAt" FROM "InternalModel2Run" WHERE "ownerId"=$1 ORDER BY "createdAt" DESC,id DESC LIMIT 20', [res.locals.userId]);
  res.json({ success: true, runs: rows.rows, limit: 20 });
});
internalModel2Router.param("id", (req, _res, next, value) => { if (!z.uuid().safeParse(value).success) throw new ValidationError("A valid internal run ID is required"); next(); });
internalModel2Router.get("/runs/:id/report", async (req, res) => {
  const report = internalReport(await ownedRun(String(req.params.id), res.locals.userId));
  if (req.query.format === "html") {
    res.set("Content-Security-Policy", "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'");
    res.type("html").send(reportHtml(report));
  } else res.json({ success: true, report });
});
internalModel2Router.get("/runs/:id/input", async (req, res) => { const row = await ownedRun(String(req.params.id), res.locals.userId); res.json({ success: true, input: row.input, inputHash: row.inputHash }); });
internalModel2Router.get("/runs/:id/replay", async (req, res) => {
  const row = await ownedRun(String(req.params.id), res.locals.userId);
  try { res.json({ success: true, replay: replayStored(row) }); }
  catch (error) { res.json({ success: true, replay: { kind: "Unavailable", reason: error instanceof Error ? error.message : "Historical replay unavailable" } }); }
});
internalModel2Router.post("/runs/:id/cancel", async (req, res) => {
  if (!z.object({}).strict().safeParse(req.body).success) throw new ValidationError("Cancellation requires an empty JSON object");
  const row = await requestCancellation(String(req.params.id), res.locals.userId); res.status(202).json({ success: true, id: row.id, status: row.status });
});

import { Pool } from "pg";
import { randomUUID } from "node:crypto";
import type { z } from "zod";
import { config } from "../utils/config";
import { ConflictError, NotFoundError, ValidationError } from "../utils/errors";
import { admissionSchema, compileEnvelope } from "./envelope";
import { contentHash } from "./identity";
import { INTERNAL_LIMITS as limits } from "./budgets";
import { boundedProduct } from "@infraforge/simulation/internal-product";
import { jsonBytes } from "./budgets";
export const internalDatabase = new Pool({ connectionString: config.DATABASE_URL, connectionTimeoutMillis: 5000, query_timeout: 10000 });
export interface InternalRunRow { id: string; ownerId: string; infrastructureId: string | null; idempotencyKey: string; requestHash: string; input: unknown; inputHash: string; status: string; token: string | null; sequence: number; throughUs: number; evidence: unknown; cancelRequested: boolean; reason: string | null; createdAt: Date; updatedAt: Date }
export async function hasInternalGrant(owner: string) { return (await internalDatabase.query('SELECT 1 FROM "InternalModel2Grant" WHERE "userId"=$1', [owner])).rowCount === 1; }
export async function admit(owner: string, request: z.infer<typeof admissionSchema>) {
  // Bound untrusted structure before hashing or borrowing a transaction connection.
  try { boundedProduct(request); jsonBytes(request, limits.requestBytes); }
  catch { throw new ValidationError("Internal request exceeds structural, text or byte budgets"); }
  const requestHash = contentHash(request), client = await internalDatabase.connect();
  try {
    await client.query("BEGIN");
    // One bounded admission critical section makes per-owner/global quotas race safe.
    await client.query("SELECT pg_advisory_xact_lock(186542854,2)");
    if (!(await client.query('SELECT 1 FROM "InternalModel2Grant" WHERE "userId"=$1 FOR SHARE', [owner])).rowCount) throw new NotFoundError();
    const existing = (await client.query<InternalRunRow>('SELECT * FROM "InternalModel2Run" WHERE "ownerId"=$1 AND "idempotencyKey"=$2', [owner, request.idempotencyKey])).rows[0];
    if (existing) {
      if (existing.requestHash !== requestHash) throw new ConflictError("Idempotency key already names a different recorded request");
      await client.query("COMMIT"); return { run: existing, created: false };
    }
    const counts = (await client.query(`SELECT count(*)::int AS total, count(*) FILTER (WHERE "ownerId"=$1)::int AS owned,
      count(*) FILTER (WHERE "ownerId"=$1 AND status IN ('queued','running'))::int AS active FROM "InternalModel2Run"`, [owner])).rows[0];
    if (counts.total >= limits.globalRuns || counts.owned >= limits.ownerRuns || counts.active >= limits.activeRuns) throw new ConflictError("Internal run retention/admission quota reached");
    const design = (await client.query('SELECT layout,"updatedAt" AT TIME ZONE \'UTC\' AS "updatedAt","challengeId" FROM "Infrastructure" WHERE id=$1 AND "ownerId"=$2 FOR SHARE', [request.infrastructureId, owner])).rows[0];
    if (!design) throw new NotFoundError("Saved design not found");
    if (design.challengeId) throw new ValidationError("Published challenge workspaces are excluded from internal Model-2 admission");
    if (design.updatedAt.toISOString() !== request.expectedDesignUpdatedAt) throw new ConflictError("Saved design changed; review it before creating a new internal run");
    const id = randomUUID(), envelope = compileEnvelope(id, owner, design.layout, design.updatedAt, request);
    const row = (await client.query<InternalRunRow>(`INSERT INTO "InternalModel2Run" (id,"ownerId","infrastructureId","idempotencyKey","requestHash",input,"inputHash")
      VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING *`, [id, owner, request.infrastructureId, request.idempotencyKey, requestHash, envelope, envelope.fingerprint])).rows[0]!;
    await client.query('INSERT INTO "Outbox" (id,"eventType",payload) VALUES ($1,\'model2-internal-created\',$2)', [randomUUID(), { internalModel2RunId: id }]);
    await client.query("COMMIT"); return { run: row, created: true };
  } catch (error) { await client.query("ROLLBACK"); throw error; } finally { client.release(); }
}
export async function ownedRun(id: string, owner: string) {
  const row = (await internalDatabase.query<InternalRunRow>('SELECT * FROM "InternalModel2Run" WHERE id=$1 AND "ownerId"=$2', [id, owner])).rows[0];
  if (!row) throw new NotFoundError("Internal run not found"); return row;
}
export async function requestCancellation(id: string, owner: string) {
  const row = (await internalDatabase.query<InternalRunRow>(`UPDATE "InternalModel2Run" SET "cancelRequested"=true,
    status=CASE WHEN status='queued' THEN 'cancelled' ELSE status END,
    reason=CASE WHEN status='queued' THEN 'Cancelled before execution' ELSE reason END,"updatedAt"=now()
    WHERE id=$1 AND "ownerId"=$2 AND status IN ('queued','running')
      AND EXISTS (SELECT 1 FROM "InternalModel2Grant" WHERE "userId"=$2) RETURNING *`, [id, owner])).rows[0];
  if (!row) { await ownedRun(id, owner); throw new ConflictError("Internal run is already terminal"); } return row;
}

import { http, API_URL } from "@/client/httpClient";
import type { AuthoringRequest, AdmissionRequest, InternalDesign, Review, RunSummary, InternalReport, ReplayResult, Diagnostic } from "@infraforge/contracts/internal-model2";
import { isAxiosError } from "axios";
const base = `${API_URL}/internal/model2`;
export async function workspace(signal?: AbortSignal) { return (await http.get<{ designs: InternalDesign[] }>(`${base}/workspace`, { signal, timeout: 15000 })).data; }
export async function validateAuthoring(body: AuthoringRequest, signal?: AbortSignal) { return (await http.post<{ review: Review }>(`${base}/validate`, body, { signal, timeout: 20000 })).data.review; }
export async function admitInternal(body: AdmissionRequest, signal?: AbortSignal) { return (await http.post<{ id: string; created: boolean }>(`${base}/runs`, body, { signal, timeout: 20000 })).data; }
export async function internalRuns(signal?: AbortSignal) { return (await http.get<{ runs: RunSummary[] }>(`${base}/runs`, { signal, timeout: 15000 })).data.runs; }
export async function internalReport(id: string, signal?: AbortSignal) { return (await http.get<{ report: InternalReport }>(`${base}/runs/${encodeURIComponent(id)}/report`, { signal, timeout: 15000 })).data.report; }
export async function replayInternal(id: string, signal?: AbortSignal) { return (await http.get<{ replay: ReplayResult }>(`${base}/runs/${encodeURIComponent(id)}/replay`, { signal, timeout: 20000 })).data.replay; }
export async function cancelInternal(id: string, signal?: AbortSignal) { await http.post(`${base}/runs/${encodeURIComponent(id)}/cancel`, {}, { signal, timeout: 15000 }); }
export function internalError(error: unknown): { message: string; denied: boolean; definitive: boolean; diagnostics: Diagnostic[] } {
  if (!isAxiosError(error)) return { message: "The request could not be completed. Your edits are preserved.", denied: false, definitive: false, diagnostics: [] };
  const status = error.response?.status;
  return { message: status === 401 ? "Your session ended. Sign in again; no new run will be submitted automatically." : status === 404 ? "Internal workspace unavailable. It may not be granted to your account or the record is unavailable." : error.response?.data?.message || "Request outcome unavailable. Retry the same reviewed submission to avoid duplication.",
    denied: status === 401 || status === 404, definitive: status === 400 || status === 409 || status === 422, diagnostics: error.response?.data?.diagnostics ?? [] };
}

import { lazy, Suspense, useEffect } from "react";
import { BrowserRouter, Navigate, Route, Routes, useLocation, useParams } from "react-router-dom";
import { Toaster } from "sonner";
import { LandingPage } from "../features/landing/pages/LandingPage";
import { SignInPage } from "../features/auth/pages/SignInPage";
import { HomePage } from "../features/dashboard/pages/HomePage";
import { NotFoundPage } from "../features/dashboard/pages/NotFoundPage";
import { ChallengesPage } from "../features/challenges/pages/ChallengesPage";
import { ChallengeDetailPage } from "../features/challenges/pages/ChallengeDetailPage";
import { DesignsPage } from "../features/designs/DesignsPage";
import { RunHistoryPage } from "../features/reports/pages/RunHistoryPage";
import { SettingsPage } from "../features/settings/SettingsPage";
import { AppShell } from "../components/shell/AppShell";
import { ProtectedRoute } from "../components/shell/ProtectedRoute";
import { PublicOnlyRoute } from "../components/shell/PublicOnlyRoute";
import { useAuthStore } from "../features/auth/store/auth.store";
import { resolvedTheme, usePreferences } from "./preferences";
import { Loading } from "../ui/Page";

// The designer and the evidence views carry most of the code; they load on first visit.
const CanvasDesignerPage = lazy(() => import("../features/canvas/components/CanvasDesignerPage").then((m) => ({ default: m.CanvasDesignerPage })));
const RunReportPage = lazy(() => import("../features/reports/pages/RunReportPage").then((m) => ({ default: m.RunReportPage })));
const ComparePage = lazy(() => import("../features/reports/pages/ComparePage").then((m) => ({ default: m.ComparePage })));
const InternalWorkspace = lazy(() => import("../features/internalModel2/InternalWorkspace").then((m) => ({ default: m.InternalWorkspace })));

// Older links keep working: /dashboard and /reports moved to /home and /runs.
function LegacyReport() {
  const { deploymentId = "" } = useParams();
  return <Navigate to={`/runs/${encodeURIComponent(deploymentId)}`} replace />;
}
function LegacyCompare() {
  const { search } = useLocation();
  return <Navigate to={`/runs/compare${search}`} replace />;
}

function ThemedToaster() {
  const theme = usePreferences((s) => s.theme);
  return <Toaster position="bottom-right" theme={resolvedTheme(theme) === "ink" ? "dark" : "light"} closeButton
    toastOptions={{ style: { background: "var(--if-raised)", border: "1px solid var(--if-line-strong)", color: "var(--if-ink)", borderRadius: "6px", fontFamily: "var(--font-sans)" } }} />;
}

function App() {
  const hydrate = useAuthStore((s) => s.hydrate);
  useEffect(() => {
    void hydrate();
    const refresh = () => { void hydrate(); };
    const expire = () => useAuthStore.getState().expire();
    window.addEventListener("focus", refresh);
    window.addEventListener("infraforge:session-ended", expire);
    const interval = setInterval(refresh, 60000);
    const channel = new BroadcastChannel("infraforge-session");
    channel.onmessage = refresh;
    return () => {
      clearInterval(interval); channel.close();
      window.removeEventListener("focus", refresh);
      window.removeEventListener("infraforge:session-ended", expire);
    };
  }, [hydrate]);

  return (
    <BrowserRouter>
      <ThemedToaster />
      <Routes>
        <Route path="/" element={<LandingPage />} />
        <Route element={<PublicOnlyRoute />}>
          <Route path="/signin" element={<SignInPage key="signin" />} />
          <Route path="/signup" element={<SignInPage key="signup" mode="signup" />} />
        </Route>
        <Route element={<ProtectedRoute />}>
          <Route element={<AppShell />}>
            <Route path="/home" element={<HomePage />} />
            <Route path="/challenges" element={<ChallengesPage />} />
            <Route path="/challenges/:challengeId" element={<ChallengeDetailPage />} />
            <Route path="/designs" element={<DesignsPage />} />
            <Route path="/runs" element={<RunHistoryPage />} />
            <Route path="/runs/compare" element={<ComparePage />} />
            <Route path="/runs/:deploymentId" element={<RunReportPage />} />
            <Route path="/settings" element={<SettingsPage />} />
            <Route path="/internal/model2" element={<InternalWorkspace />} />
          </Route>
          {/* The designer and live runs are full-screen workspaces with their own bar. */}
          <Route path="/design" element={<Suspense fallback={<div className="grid h-dvh place-items-center bg-canvas"><Loading label="Opening the designer…" /></div>}><CanvasDesignerPage /></Suspense>} />
          <Route path="/dashboard" element={<Navigate to="/home" replace />} />
          <Route path="/reports" element={<Navigate to="/runs" replace />} />
          <Route path="/reports/compare" element={<LegacyCompare />} />
          <Route path="/reports/:deploymentId" element={<LegacyReport />} />
        </Route>
        <Route path="*" element={<NotFoundPage />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;

import { Suspense, useEffect, useState } from "react";
import { Link, NavLink, Outlet } from "react-router-dom";
import { Wordmark } from "@/ui/Brand";
import { cx } from "@/ui/cx";
import { Loading, Page } from "@/ui/Page";
import { AccountMenu } from "./AccountMenu";
import { workspace } from "@/api/internalModel2.api";
import { useAuthStore } from "@/features/auth/store/auth.store";

const NAV = [
  { to: "/home", label: "Home" },
  { to: "/challenges", label: "Challenges" },
  { to: "/designs", label: "Designs" },
  { to: "/runs", label: "Runs" },
] as const;

export function SkipLink() {
  return <a href="#main" className="sr-only focus:not-sr-only focus:fixed focus:top-2 focus:left-2 focus:z-[100] focus:rounded-md focus:bg-ink focus:px-3 focus:py-2 focus:text-inverse">Skip to content</a>;
}

function NavItems({ className, internal }: { className?: string; internal: boolean }) {
  return (
    <ul className={cx("flex items-center gap-1", className)}>
      {NAV.map((item) => (
        <li key={item.to}>
          <NavLink to={item.to} className={({ isActive }) => cx("relative inline-flex h-9 items-center rounded-md px-3 text-sm font-medium transition-colors",
            isActive ? "text-ink after:absolute after:inset-x-3 after:-bottom-[11px] after:h-[2px] after:bg-ink" : "text-ink-3 hover:bg-sunken hover:text-ink")}>
            {item.label}
          </NavLink>
        </li>
      ))}
      {internal && <li className="shrink-0"><NavLink to="/internal/model2" className="inline-flex h-9 items-center whitespace-nowrap rounded-md px-3 text-sm text-ink-2 hover:bg-sunken">Model 2 · internal</NavLink></li>}
    </ul>
  );
}

/* Paper shell: one top bar, four destinations, account on the right.
Narrow screens keep the same four links in a scrollable second row. */
export function AppShell() {
  const owner = useAuthStore((s) => s.user?.id), [grantedOwner, setGrantedOwner] = useState<string | null>(null);
  useEffect(() => {
    const controller = new AbortController();
    if (owner) void workspace(controller.signal).then(() => { if (!controller.signal.aborted) setGrantedOwner(owner); }).catch(() => { if (!controller.signal.aborted) setGrantedOwner(null); });
    return () => controller.abort();
  }, [owner]);
  return (
    <div className="min-h-dvh bg-bg text-ink">
      <SkipLink />
      <header className="sticky top-0 z-30 border-b border-line bg-bg/95 backdrop-blur-sm">
        <div className="mx-auto flex h-14 max-w-[1360px] items-center gap-6 px-4 sm:px-6 lg:px-8">
          <Link to="/home" aria-label="InfraForge home" className="rounded-md"><Wordmark /></Link>
          <nav aria-label="Primary" className="hidden flex-1 md:block"><NavItems internal={!!owner && grantedOwner === owner} /></nav>
          <div className="ml-auto md:ml-0"><AccountMenu /></div>
        </div>
        <nav aria-label="Primary" className="if-scroll overflow-x-auto overflow-y-hidden border-t border-line px-2 md:hidden"><NavItems internal={!!owner && grantedOwner === owner} className="h-11" /></nav>
      </header>
      <main id="main" tabIndex={-1} className="outline-none"><Suspense fallback={<Page><Loading label="Loading…" /></Page>}><Outlet /></Suspense></main>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import type { InternalReport as Report, Json, ReplayResult } from "@infraforge/contracts/internal-model2";
import * as api from "@/api/internalModel2.api";
import { Button } from "@/ui/Button";
import { Notice, Loading } from "@/ui/Page";
function Value({ value }: { value: Json }) {
  if (value === null) return <span>Unavailable</span>;
  if (Array.isArray(value)) return <ul className="space-y-2">{value.map((v, i) => <li key={i} className="border-l border-line pl-3"><Value value={v} /></li>)}</ul>;
  if (typeof value === "object") return <dl className="space-y-1">{Object.entries(value).map(([key, child]) => <div key={key} className="flex flex-wrap gap-x-3"><dt className="font-medium">{key}</dt><dd className="min-w-0 break-words"><Value value={child} /></dd></div>)}</dl>;
  return <span>{String(value)}</span>;
}
export function InternalReport({ id, blocked }: { id: string; blocked: () => void }) {
  const [report, setReport] = useState<Report | null>(null), [error, setError] = useState(""), [busy, setBusy] = useState(false), [replay, setReplay] = useState<ReplayResult | null>(null), [version, setVersion] = useState(0), [stopped, setStopped] = useState(false);
  const action = useRef(false), control = useRef(new AbortController()), region = useRef<HTMLElement>(null);
  useEffect(() => { region.current?.focus(); }, [id]);
  useEffect(() => {
    const controller = new AbortController(); control.current = controller; let timer: ReturnType<typeof setTimeout> | undefined, count = 0;
    const read = async () => {
      try { const value = await api.internalReport(id, controller.signal); if (controller.signal.aborted) return; setReport(value); setError(""); if (!value.replay.compatible) setReplay(null);
        if (["queued", "running"].includes(value.status) && ++count < 60) timer = setTimeout(() => { void read(); }, 2000);
        else setStopped(["queued", "running"].includes(value.status));
      } catch (e) { if (!controller.signal.aborted) { const detail = api.internalError(e); setError(detail.message); if (detail.denied) { setReport(null); blocked(); } } }
    };
    void read(); return () => { controller.abort(); clearTimeout(timer); };
  }, [id, version, blocked]);
  const act = async (kind: "cancel" | "replay") => {
    if (action.current) return; action.current = true; setBusy(true);
    const signal = control.current.signal;
    try { if (kind === "cancel") { await api.cancelInternal(id, signal); if (!signal.aborted) setVersion((v) => v + 1); } else { const value = await api.replayInternal(id, signal); if (!signal.aborted) setReplay(value); } }
    catch (e) { if (!signal.aborted) { const detail = api.internalError(e); setError(detail.message); if (detail.denied) { setReport(null); blocked(); } } }
    finally { action.current = false; if (!signal.aborted) setBusy(false); }
  };
  return <section ref={region} tabIndex={-1} aria-label="Durable Model-2 report" className="mt-10 space-y-5 border-t border-line pt-6 outline-none">
    <h2 className="text-2xl font-semibold">Last durable result</h2><p className="break-all text-sm text-ink-3">Run {id}</p>
    {error && <Notice tone="fail" role="alert">{error}</Notice>}
    {!report && !error && <Loading label="Reading retained evidence…" />}
    <Button size="sm" disabled={busy} onClick={() => { setStopped(false); setVersion((v) => v + 1); }}>Refresh durable report</Button>
    {stopped && <p role="status">Automatic refresh stopped after 60 reads. Refresh manually to read the latest committed state.</p>}
    {report && <>
      <p role="status" className="font-semibold">Status: {report.status} · capture {report.sequence} · through {report.throughUs} us</p>
      <p className="text-sm">{report.reason || "Lifecycle status is the last committed state, not a worker liveness signal."} {report.status !== "completed" && "Retained prefix only; missing work is not zero. Crashed executions are not resumed."}</p>
      {report.problems.length > 0 && <Notice tone="fail">{report.problems.join(" ")}</Notice>}
      <div className="flex flex-wrap gap-3"><Button loading={busy} disabled={!report.replay.compatible} onClick={() => { void act("replay"); }}>Verify deterministic replay</Button>{["queued", "running"].includes(report.status) && <Button disabled={busy} onClick={() => { void act("cancel"); }}>Cancel this run</Button>}</div>
      <p className="text-sm">{report.replay.reason} Cancellation stops at a capture boundary and retains its committed prefix.</p>
      {replay && <Notice><span role="status">Replay: {replay.kind}. {replay.reason} {replay.complete === false ? "Matches a prefix only, not a complete execution." : replay.complete ? "Complete recorded capture matches." : ""} {replay.mutation}</span></Notice>}
      <div className="grid gap-6 lg:grid-cols-2">{[["Observed modeled facts", report.observed], ["Interpreted", report.interpreted]] .map(([title, rows]) => <section key={String(title)} className="rounded-md border border-line p-4"><h3 className="mb-3 font-semibold">{String(title)}</h3><Value value={rows as Json} /></section>)}</div>
      <section className="rounded-md border border-line p-4"><h3 className="mb-3 font-semibold">Unknown and uncertainties</h3><ul className="list-disc space-y-2 pl-5 text-sm">{report.unknown.map((s) => <li key={s}>{s}</li>)}</ul></section>
      {[["Service activity, commands, object state and faults", report.state], ["Usage evidence", report.usage], ["Retained checkpoint history", report.checkpoints]].map(([title, value]) => <details key={String(title)} className="rounded-md border border-line p-4"><summary className="cursor-pointer font-semibold">{String(title)}</summary><div className="mt-4 text-sm"><Value value={value as Json} /></div></details>)}
      <details><summary className="cursor-pointer text-sm underline">Input and execution identity</summary><p className="break-all text-xs">Input {report.inputHash}<br />Source {report.source ?? "Unknown"}</p></details>
    </>}
  </section>;
}

